import{_ as e,c as a,o as i,a0 as t}from"./chunks/framework.DKRgXLPU.js";const o=JSON.parse('{"title":"Introduction au jeu mental - Diapositives pour l&#39;animateur","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/fr/facilitator-slides.md","filePath":"public/downloads/fr/facilitator-slides.md"}');const r=e({name:"public/downloads/fr/facilitator-slides.md"},[["render",function(e,o,r,s,n,u){return i(),a("div",null,[...o[0]||(o[0]=[t('<h1 id="introduction-au-jeu-mental-diapositives-pour-l-39-animateur" tabindex="-1">Introduction au jeu mental - Diapositives pour l&#39;animateur <a class="header-anchor" href="#introduction-au-jeu-mental-diapositives-pour-l-39-animateur" aria-label="Permalink to &quot;Introduction au jeu mental - Diapositives pour l&amp;#39;animateur&quot;">​</a></h1><p><strong>Académie de Pétanque</strong><em>Guide de session pour les animateurs</em></p><hr><h2 id="diapositive-1-bienvenue" tabindex="-1">Diapositive 1 : Bienvenue <a class="header-anchor" href="#diapositive-1-bienvenue" aria-label="Permalink to &quot;Diapositive 1 : Bienvenue&quot;">​</a></h2><h1 id="🎯-introduction-au-jeu-mental" tabindex="-1">🎯 Introduction au jeu mental <a class="header-anchor" href="#🎯-introduction-au-jeu-mental" aria-label="Permalink to &quot;🎯 Introduction au jeu mental&quot;">​</a></h1><p><strong>Pour les joueurs de pétanque élite</strong></p><h3 id="aujourd-39-hui-vous-decouvrirez" tabindex="-1">Aujourd&#39;hui, vous découvrirez : <a class="header-anchor" href="#aujourd-39-hui-vous-decouvrirez" aria-label="Permalink to &quot;Aujourd&amp;#39;hui, vous découvrirez :&quot;">​</a></h3><ul><li>🧠 Comment créer les conditions idéales pour « la zone »</li><li>💪 Comment faire taire sa voix intérieure critique</li><li>🎪 Des outils pratiques qui fonctionnent sous pression</li></ul><p><strong>Préparez-vous pour une session interactive !</strong></p><hr><h2 id="diapo-2-sondage-rapide-–-levez-la-main-🙋" tabindex="-1">Diapo 2 : Sondage rapide – Levez la main ! 🙋 <a class="header-anchor" href="#diapo-2-sondage-rapide-–-levez-la-main-🙋" aria-label="Permalink to &quot;Diapo 2 : Sondage rapide – Levez la main ! 🙋&quot;">​</a></h2><h3 id="qui-a-deja-vecu-ca" tabindex="-1">Qui a déjà vécu ça ? <a class="header-anchor" href="#qui-a-deja-vecu-ca" aria-label="Permalink to &quot;Qui a déjà vécu ça ?&quot;">​</a></h3><p><strong>Levez la main si vous avez déjà :</strong></p><ol><li><p>Un tir parfait à l&#39;entraînement… et raté en compétition ? 🎯❌</p></li><li><p>Vous avez eu l&#39;impression que vos pensées s&#39;emballaient alors que vous aviez besoin de rester calme ? 🧠💨</p></li><li><p>Vous vous êtes critiqué après une erreur ? 😤</p></li><li><p>Vous avez déjà joué à un jeu où tout s&#39;est parfaitement déroulé ? ✨</p></li></ol><p><strong>Vous n&#39;êtes pas seul ! Essayons de régler ce problème ensemble.</strong></p><hr><h2 id="diapositive-3-le-paradoxe-du-joueur-d-39-elite" tabindex="-1">Diapositive 3 : Le paradoxe du joueur d&#39;élite <a class="header-anchor" href="#diapositive-3-le-paradoxe-du-joueur-d-39-elite" aria-label="Permalink to &quot;Diapositive 3 : Le paradoxe du joueur d&amp;#39;élite&quot;">​</a></h2><h3 id="vous-possedez-deja-les-competences-alors-pourquoi" tabindex="-1">Vous possédez déjà les compétences… Alors pourquoi ? <a class="header-anchor" href="#vous-possedez-deja-les-competences-alors-pourquoi" aria-label="Permalink to &quot;Vous possédez déjà les compétences… Alors pourquoi ?&quot;">​</a></h3><p><strong>✅ Vous AVEZ :</strong></p><ul><li>Excellente technique (des milliers d&#39;heures)</li><li>Des années d&#39;expérience</li><li>capacités physiques</li></ul><p><strong>❌ Mais vous avez des DIFFICULTÉS avec :</strong></p><ul><li>Accéder à cette technique sous pression</li><li>Rester constant en compétition</li><li>Se relever après des erreurs</li></ul><h3 id="la-piece-manquante-🧩" tabindex="-1">La pièce manquante ? 🧩 <a class="header-anchor" href="#la-piece-manquante-🧩" aria-label="Permalink to &quot;La pièce manquante ? 🧩&quot;">​</a></h3><p><strong>Votre mental.</strong></p><p>« La différence entre le bien et l&#39;excellence réside dans ce qui se passe dans votre tête. »</p><hr><h2 id="diapo-4-la-zone-–-vous-connaissez-cette-sensation-⚡" tabindex="-1">Diapo 4 : La zone – Vous connaissez cette sensation ! ⚡ <a class="header-anchor" href="#diapo-4-la-zone-–-vous-connaissez-cette-sensation-⚡" aria-label="Permalink to &quot;Diapo 4 : La zone – Vous connaissez cette sensation ! ⚡&quot;">​</a></h2><h3 id="vous-vous-souvenez-de-ce-match-parfait" tabindex="-1">Vous vous souvenez de ce match parfait ? <a class="header-anchor" href="#vous-vous-souvenez-de-ce-match-parfait" aria-label="Permalink to &quot;Vous vous souvenez de ce match parfait ?&quot;">​</a></h3><p><strong>Tout ce que j&#39;ai ressenti :</strong></p><ul><li>⏱️ Le temps a ralenti</li><li>🎯 Sans effort et automatique</li><li>🧘 Concentration totale</li><li>🎪 Impossible de rater ça</li></ul><h3 id="c-39-est-«-la-zone-»-etat-de-flux" tabindex="-1">C&#39;est « La Zone » (État de flux) <a class="header-anchor" href="#c-39-est-«-la-zone-»-etat-de-flux" aria-label="Permalink to &quot;C&amp;#39;est « La Zone » (État de flux)&quot;">​</a></h3><p><strong>La question :</strong><em>Comment y accéder de manière constante, et non par hasard ?</em></p><p><strong>La réponse :</strong><em>Comprendre vos deux modes de pensée...</em></p><hr><h2 id="diapo-5-votre-cerveau-a-deux-modes-🧠" tabindex="-1">Diapo 5 : Votre cerveau a deux modes 🧠 <a class="header-anchor" href="#diapo-5-votre-cerveau-a-deux-modes-🧠" aria-label="Permalink to &quot;Diapo 5 : Votre cerveau a deux modes 🧠&quot;">​</a></h2><h3 id="🤔-mode-planification-cerveau-analytique" tabindex="-1">🤔 MODE PLANIFICATION (Cerveau analytique) <a class="header-anchor" href="#🤔-mode-planification-cerveau-analytique" aria-label="Permalink to &quot;🤔 MODE PLANIFICATION (Cerveau analytique)&quot;">​</a></h3><p><strong>Quand l&#39;utiliser :</strong> AVANT la prise de vue</p><ul><li>📊 Analyse du terrain</li><li>🎯 Choisir votre stratégie</li><li>⚖️ Évaluer les risques</li><li>🤝 Choisir le bon cliché</li></ul><h3 id="🎯-mode-d-39-execution-flow-brain" tabindex="-1">🎯 MODE D&#39;EXÉCUTION (Flow Brain) <a class="header-anchor" href="#🎯-mode-d-39-execution-flow-brain" aria-label="Permalink to &quot;🎯 MODE D&amp;#39;EXÉCUTION (Flow Brain)&quot;">​</a></h3><p><strong>Quand l&#39;utiliser :</strong> PENDANT la prise de vue</p><ul><li>💪 Faites confiance à votre corps</li><li>🚫 NE PAS penser à la technique</li><li>⏰ Le moment présent seulement</li><li>🤖 Performance automatique</li></ul><h3 id="⚠️-le-probleme" tabindex="-1">⚠️ LE PROBLÈME : <a class="header-anchor" href="#⚠️-le-probleme" aria-label="Permalink to &quot;⚠️ LE PROBLÈME :&quot;">​</a></h3><p><strong>La plupart des joueurs restent en mode planification pendant l&#39;exécution !</strong><em>Votre cerveau analytique interfère avec vos performances automatiques.</em></p><hr><h2 id="diapo-6-le-switch-–-votre-arme-secrete-🔄" tabindex="-1">Diapo 6 : Le Switch – Votre arme secrète 🔄 <a class="header-anchor" href="#diapo-6-le-switch-–-votre-arme-secrete-🔄" aria-label="Permalink to &quot;Diapo 6 : Le Switch – Votre arme secrète 🔄&quot;">​</a></h2><h3 id="maitrisez-cette-competence" tabindex="-1">Maîtrisez cette compétence : <a class="header-anchor" href="#maitrisez-cette-competence" aria-label="Permalink to &quot;Maîtrisez cette compétence :&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>BEFORE the shot:          DURING the shot:</span></span>\n<span class="line"><span>🤔 Planning Mode    →     🎯 Execution Mode</span></span></code></pre></div><h3 id="le-processus" tabindex="-1">Le processus : <a class="header-anchor" href="#le-processus" aria-label="Permalink to &quot;Le processus :&quot;">​</a></h3><p><strong>1️⃣ AVANT (10-15 secondes) :</strong></p><ul><li>🤔 Tout analyser</li><li>📊 Élaborez votre stratégie</li><li>✅ Prenez votre décision</li></ul><p><strong>2️⃣ LE COMMUTATEUR (3 respirations) :</strong></p><ul><li>🌬️ Respirez profondément</li><li>🧘 Faites le vide dans votre esprit</li><li>🔄 Laissez tomber l&#39;analyse</li></ul><p><strong>3️⃣ PENDANT (2-3 secondes) :</strong></p><ul><li>🎯 Faites-nous entièrement confiance</li><li>🤖 Laisse faire</li><li>⚡ Exécution automatique</li></ul><p><strong>Maîtrisez cette technique = Accès au flux à la demande !</strong></p><hr><h2 id="diapo-7-activite-–-essayez-la-maintenant-🎯" tabindex="-1">Diapo 7 : ACTIVITÉ – Essayez-la maintenant ! 🎯 <a class="header-anchor" href="#diapo-7-activite-–-essayez-la-maintenant-🎯" aria-label="Permalink to &quot;Diapo 7 : ACTIVITÉ – Essayez-la maintenant ! 🎯&quot;">​</a></h2><h3 id="entrainons-nous-a-changer-de-position-2-minutes" tabindex="-1">Entraînons-nous à changer de position (2 minutes) <a class="header-anchor" href="#entrainons-nous-a-changer-de-position-2-minutes" aria-label="Permalink to &quot;Entraînons-nous à changer de position (2 minutes)&quot;">​</a></h3><p><strong>Tout le monde debout !</strong></p><ol><li><p><strong>Mode planification (10 sec) :</strong> Imaginez analyser un tir. Pensez au terrain, à la stratégie, aux risques.</p></li><li><p><strong>Le changement (3 respirations) :</strong> Prenez 3 respirations profondes. Videz votre esprit à chaque expiration.</p></li><li><p><strong>Mode d&#39;exécution (3 sec) :</strong> Imaginez lancer. Sans réfléchir. Juste faire confiance et laisser faire.</p></li></ol><p><strong>Qu&#39;avez-vous ressenti ? C&#39;était différent ?</strong></p><p>Asseyez-vous et discutons-en...</p><hr><h2 id="diapo-8-rencontrez-votre-critique-interieure-😈" tabindex="-1">Diapo 8 : Rencontrez votre critique intérieure 😈 <a class="header-anchor" href="#diapo-8-rencontrez-votre-critique-interieure-😈" aria-label="Permalink to &quot;Diapo 8 : Rencontrez votre critique intérieure 😈&quot;">​</a></h2><h3 id="cette-voix-vous-semble-familiere" tabindex="-1">Cette voix vous semble familière ? <a class="header-anchor" href="#cette-voix-vous-semble-familiere" aria-label="Permalink to &quot;Cette voix vous semble familière ?&quot;">​</a></h3><p><strong>Après un mauvais tir :</strong></p><ul><li>💢 « C&#39;était TERRIBLE ! »</li><li>😤 « Tu fais TOUJOURS des erreurs sous la pression ! »</li><li>😰 « Tout le monde te regarde échouer ! »</li><li>😞 « Tu n&#39;es tout simplement pas assez bon ! »</li></ul><h3 id="sondage-rapide-🙋" tabindex="-1">Sondage rapide : 🙋 <a class="header-anchor" href="#sondage-rapide-🙋" aria-label="Permalink to &quot;Sondage rapide : 🙋&quot;">​</a></h3><p><strong>Qui entend régulièrement cette voix ?</strong></p><h3 id="la-verite" tabindex="-1">La vérité : <a class="header-anchor" href="#la-verite" aria-label="Permalink to &quot;La vérité :&quot;">​</a></h3><p><strong>Votre critique intérieure essaie de vous aider...</strong><em>Mais en réalité, cela nuit à vos performances.</em></p><hr><h2 id="diapo-9-virez-votre-critique-engagez-votre-coach-🔄" tabindex="-1">Diapo 9 : Virez votre critique, engagez votre coach ! 🔄 <a class="header-anchor" href="#diapo-9-virez-votre-critique-engagez-votre-coach-🔄" aria-label="Permalink to &quot;Diapo 9 : Virez votre critique, engagez votre coach ! 🔄&quot;">​</a></h2><h3 id="la-transformation" tabindex="-1">La transformation : <a class="header-anchor" href="#la-transformation" aria-label="Permalink to &quot;La transformation :&quot;">​</a></h3><table tabindex="0"><thead><tr><th>😈 Critique intérieure</th><th>➡️</th><th>😊 Coach intérieur</th></tr></thead><tbody><tr><td>&quot;Tu te trompes TOUJOURS !&quot;</td><td>→</td><td>&quot;J&#39;ai déjà réussi ce tir 1000 fois&quot;</td></tr><tr><td>&quot;C&#39;était TERRIBLE !&quot;</td><td>→</td><td>&quot;Que puis-je en tirer ?&quot;</td></tr><tr><td>&quot;Tout le monde te juge !&quot;</td><td>→</td><td>&quot;Concentre-toi sur MON jeu, pas sur leurs opinions&quot;</td></tr><tr><td>&quot;Tu n&#39;es pas assez bon !&quot;</td><td>→</td><td>&quot;Je m&#39;améliore chaque jour&quot;</td></tr></tbody></table><h3 id="l-39-impact" tabindex="-1">L&#39;impact : <a class="header-anchor" href="#l-39-impact" aria-label="Permalink to &quot;L&amp;#39;impact :&quot;">​</a></h3><p><strong>Critique = Anxiété, tension, mauvaise performance</strong><strong>Coaching = Confiance, détente, performance optimale</strong></p><hr><h2 id="diapo-10-activite-–-repensez-votre-critique-💬" tabindex="-1">Diapo 10 : ACTIVITÉ – Repensez votre critique ! 💬 <a class="header-anchor" href="#diapo-10-activite-–-repensez-votre-critique-💬" aria-label="Permalink to &quot;Diapo 10 : ACTIVITÉ – Repensez votre critique ! 💬&quot;">​</a></h2><h3 id="exercice-en-binome-3-minutes" tabindex="-1">Exercice en binôme (3 minutes) <a class="header-anchor" href="#exercice-en-binome-3-minutes" aria-label="Permalink to &quot;Exercice en binôme (3 minutes)&quot;">​</a></h3><p><strong>Tournez-vous vers la personne à côté de vous :</strong></p><p><strong>Personne A (1,5 min) :</strong></p><ol><li>Partagez une chose que votre critique intérieure vous dit</li><li>Votre partenaire vous aide à le reformuler comme un coach intérieur.</li><li>Notez la nouvelle phrase</li></ol><p><strong>Personne B (1,5 min) :</strong></p><ol><li>Même processus</li><li>Partagez vos pensées sur votre critique intérieure</li><li>Obtenez de l&#39;aide pour le reformuler.</li></ol><p><strong>Prêts ? Partez !</strong></p><p><em>Nous partagerons quelques exemples avec le groupe après...</em></p><hr><h2 id="diapositive-11-outil-n°-1-la-reinitialisation-en-3-respirations-🌬️" tabindex="-1">Diapositive 11 : Outil n° 1 - La réinitialisation en 3 respirations 🌬️ <a class="header-anchor" href="#diapositive-11-outil-n°-1-la-reinitialisation-en-3-respirations-🌬️" aria-label="Permalink to &quot;Diapositive 11 : Outil n° 1 - La réinitialisation en 3 respirations 🌬️&quot;">​</a></h2><h3 id="votre-soupape-de-decharge-de-pression-d-39-urgence" tabindex="-1">Votre soupape de décharge de pression d&#39;urgence <a class="header-anchor" href="#votre-soupape-de-decharge-de-pression-d-39-urgence" aria-label="Permalink to &quot;Votre soupape de décharge de pression d&amp;#39;urgence&quot;">​</a></h3><p><strong>Utilisez ceci lorsque :</strong></p><ul><li>😤 Tu viens de faire une erreur</li><li>😰 Vous sentez la pression monter</li><li>🤯 Votre esprit s&#39;emballe</li></ul><h3 id="le-processus-1" tabindex="-1">Le processus : <a class="header-anchor" href="#le-processus-1" aria-label="Permalink to &quot;Le processus :&quot;">​</a></h3><p><strong>🌬️ RESPIRATION 1 (Inspirer 4 sec) :</strong> Observez où vous ressentez des tensions (épaules ? mâchoire ? estomac ?).</p><p><strong>🌬️ RESPIRATION 2 (Expiration 6 sec) :</strong> Relâchez cette tension. Laissez-la s&#39;évacuer avec votre respiration.</p><p><strong>🌬️ RESPIRATION 3 (Inspirez 4 fois, Expirez 6 fois) :</strong> Concentrez-vous sur le présent. Cette photo. Cet instant. Rien d&#39;autre.</p><p><strong>⏱️ Cela prend 20 secondes. Cela change tout.</strong></p><hr><h2 id="diapo-12-demo-–-a-vous-d-essayer-🌬️" tabindex="-1">Diapo 12 : DÉMO – À vous d’essayer ! 🌬️ <a class="header-anchor" href="#diapo-12-demo-–-a-vous-d-essayer-🌬️" aria-label="Permalink to &quot;Diapo 12 : DÉMO – À vous d’essayer ! 🌬️&quot;">​</a></h2><h3 id="exercice-de-reinitialisation-par-la-respiration-en-3-etapes-1-minute" tabindex="-1">Exercice de réinitialisation par la respiration en 3 étapes (1 minute) <a class="header-anchor" href="#exercice-de-reinitialisation-par-la-respiration-en-3-etapes-1-minute" aria-label="Permalink to &quot;Exercice de réinitialisation par la respiration en 3 étapes (1 minute)&quot;">​</a></h3><p><strong>Fermez tous les yeux...</strong></p><p><strong>Respiration 1 :</strong><em>Inspirez pendant 4 secondes... Où ressentez-vous des tensions ?</em></p><p><strong>Respiration 2 :</strong><em>Expirez pendant 6 secondes... Relâchez prise...</em></p><p><strong>Respiration 3 :</strong><em>Entrée pour 4, sortie pour 6... Uniquement l&#39;instant présent...</em></p><p><strong>Ouvrez les yeux. Comment vous sentez-vous ?</strong></p><p><em>Ceci est votre bouton de réinitialisation. Utilisez-le !</em></p><hr><h2 id="diapo-13-outil-n°-2-votre-routine-d-avant-prise-de-vue-🎯" tabindex="-1">Diapo 13 : Outil n° 2 - Votre routine d’avant-prise de vue 🎯 <a class="header-anchor" href="#diapo-13-outil-n°-2-votre-routine-d-avant-prise-de-vue-🎯" aria-label="Permalink to &quot;Diapo 13 : Outil n° 2 - Votre routine d’avant-prise de vue 🎯&quot;">​</a></h2><h3 id="creer-une-coherence-automatique" tabindex="-1">Créer une cohérence automatique <a class="header-anchor" href="#creer-une-coherence-automatique" aria-label="Permalink to &quot;Créer une cohérence automatique&quot;">​</a></h3><p><strong>La routine en 4 étapes :</strong></p><p><strong>1️⃣ VISUALISER (3 secondes)</strong> Visualisez le tir parfait. Imaginez-le atterrir exactement où vous le souhaitez.</p><p><strong>2️⃣ RESPIREZ (2 secondes)</strong> Une grande inspiration. Passez du mode planification au mode exécution.</p><p><strong>3️⃣ ANCRE (2 secondes)</strong> Touchez votre boule. Sentez son poids. Connexion physique.</p><p><strong>4️⃣ EXÉCUTER (2 secondes)</strong> Ayez une confiance totale. Laissez votre corps faire ce qu&#39;il sait faire.</p><p><strong>⏱️ Total : 9 secondes. Identique à chaque fois.</strong></p><h3 id="pourquoi-ca-marche" tabindex="-1">Pourquoi ça marche : <a class="header-anchor" href="#pourquoi-ca-marche" aria-label="Permalink to &quot;Pourquoi ça marche :&quot;">​</a></h3><p><strong>La constance = la confiance = la performance</strong></p><hr><h2 id="diapositive-14-outil-n°-3-–-protocole-de-recuperation-des-erreurs-🔄" tabindex="-1">Diapositive 14 : Outil n° 3 – Protocole de récupération des erreurs 🔄 <a class="header-anchor" href="#diapositive-14-outil-n°-3-–-protocole-de-recuperation-des-erreurs-🔄" aria-label="Permalink to &quot;Diapositive 14 : Outil n° 3 – Protocole de récupération des erreurs 🔄&quot;">​</a></h2><h3 id="mauvaise-photo-voici-votre-plan-de-recuperation-en-4-etapes" tabindex="-1">Mauvaise photo ? Voici votre plan de récupération en 4 étapes : <a class="header-anchor" href="#mauvaise-photo-voici-votre-plan-de-recuperation-en-4-etapes" aria-label="Permalink to &quot;Mauvaise photo ? Voici votre plan de récupération en 4 étapes :&quot;">​</a></h3><p><strong>1️⃣ ACCUSÉ DE RÉCEPTION (2 secondes)</strong> « Ça ne s&#39;est pas passé comme prévu. » (Sans jugement, juste un constat.)</p><p><strong>2️⃣ LIBÉRATION (3 secondes)</strong> Réinitialisation physique : secouez vos mains, faites rouler vos épaules, marchez 3 pas.</p><p><strong>3️⃣ REFOCUS (3 secondes)</strong> « La prochaine occasion est une NOUVELLE opportunité. » (Sans lien avec la précédente)</p><p><strong>4️⃣ EXÉCUTER (Utilisez votre routine)</strong> Faites confiance à votre routine d&#39;avant-injection. Nouveau départ.</p><h3 id="l-39-idee-cle" tabindex="-1">L&#39;idée clé : <a class="header-anchor" href="#l-39-idee-cle" aria-label="Permalink to &quot;L&amp;#39;idée clé :&quot;">​</a></h3><p><strong>Chaque prise de vue est indépendante. Ne reproduisez pas vos erreurs.</strong></p><p><em>Les meilleurs joueurs oublient le moins possible leurs mauvais coups.</em></p><hr><h2 id="diapo-15-parlons-vrai-qu-39-est-ce-qui-vous-freine-💬" tabindex="-1">Diapo 15 : PARLONS VRAI - Qu&#39;est-ce qui vous freine ? 💬 <a class="header-anchor" href="#diapo-15-parlons-vrai-qu-39-est-ce-qui-vous-freine-💬" aria-label="Permalink to &quot;Diapo 15 : PARLONS VRAI - Qu&amp;#39;est-ce qui vous freine ? 💬&quot;">​</a></h2><h3 id="discussion-de-groupe-5-minutes" tabindex="-1">Discussion de groupe (5 minutes) <a class="header-anchor" href="#discussion-de-groupe-5-minutes" aria-label="Permalink to &quot;Discussion de groupe (5 minutes)&quot;">​</a></h3><p><strong>Votre avis nous intéresse :</strong></p><p><strong>Question 1 :</strong> « Quand vous sentez-vous le plus en état de flow ? Quelles conditions vous y aident ? »</p><p><strong>Question 2 :</strong> « Quel est votre plus grand défi mental en compétition ? »</p><p><strong>Question 3 :</strong> « Lequel de ces outils vous parle le plus ? »</p><ul><li>Réinitialisation en 3 respirations</li><li>Routine avant le tir</li><li>Recadrage du coach intérieur</li><li>Récupération d&#39;erreurs</li></ul><p><strong>Partagez ouvertement - c&#39;est un espace sûr !</strong></p><hr><h2 id="diapositive-16-votre-plan-d-action-–-choisissez-en-un-✅" tabindex="-1">Diapositive 16 : Votre plan d’action – Choisissez-en UN ! ✅ <a class="header-anchor" href="#diapositive-16-votre-plan-d-action-–-choisissez-en-un-✅" aria-label="Permalink to &quot;Diapositive 16 : Votre plan d’action – Choisissez-en UN ! ✅&quot;">​</a></h2><h3 id="le-defi-de-cette-semaine" tabindex="-1">Le défi de cette semaine : <a class="header-anchor" href="#le-defi-de-cette-semaine" aria-label="Permalink to &quot;Le défi de cette semaine :&quot;">​</a></h3><p><strong>Choisissez UNE SEULE technique à pratiquer :</strong></p><p><strong>Option A : 🌬️ Réinitialisation en 3 respirations</strong> À utiliser après CHAQUE erreur d&#39;entraînement</p><p><strong>Option B : 🎯 Routine d&#39;avant-tir</strong> Même routine en 4 étapes à CHAQUE lancer</p><p><strong>Option C : 💬 Coach intérieur</strong> Reformuler UNE pensée critique par séance</p><p><strong>Option D : 🔄 Changement de mode</strong> Planification des exercices → passage à l&#39;exécution</p><h3 id="pourquoi-un-seul" tabindex="-1">Pourquoi un seul ? <a class="header-anchor" href="#pourquoi-un-seul" aria-label="Permalink to &quot;Pourquoi un seul ?&quot;">​</a></h3><p><strong>Maîtrisez un outil avant d&#39;en ajouter un autre.</strong><em>Dans l&#39;entraînement mental, la profondeur prime sur la largeur.</em></p><hr><h2 id="diapositive-17-suivez-vos-progres-📊" tabindex="-1">Diapositive 17 : Suivez vos progrès 📊 <a class="header-anchor" href="#diapositive-17-suivez-vos-progres-📊" aria-label="Permalink to &quot;Diapositive 17 : Suivez vos progrès 📊&quot;">​</a></h2><h3 id="ce-qu-39-il-faut-retenir-cette-semaine" tabindex="-1">Ce qu&#39;il faut retenir cette semaine : <a class="header-anchor" href="#ce-qu-39-il-faut-retenir-cette-semaine" aria-label="Permalink to &quot;Ce qu&amp;#39;il faut retenir cette semaine :&quot;">​</a></h3><p><strong>🎯 Moments de flow :</strong></p><ul><li>À quel moment vous êtes-vous senti « dans la zone » ?</li><li>À quelle heure de la journée ?</li><li>Quel type de tir ?</li><li>Qu&#39;est-ce qui vous a permis d&#39;y arriver ?</li></ul><p><strong>💪 Technique de réussite :</strong></p><ul><li>Quel outil a le mieux fonctionné ?</li><li>Quand l&#39;avez-vous utilisé ?</li><li>Quel a été le résultat ?</li></ul><p><strong>📝 Tenir un journal simple :</strong><em>&quot;Utilisation de la technique de réinitialisation en 3 respirations après une erreur → sentiment de calme retrouvé → prise de la photo suivante&quot;</em></p><h3 id="l-39-objectif" tabindex="-1">L&#39;objectif : <a class="header-anchor" href="#l-39-objectif" aria-label="Permalink to &quot;L&amp;#39;objectif :&quot;">​</a></h3><p><strong>Trouvez VOS schémas. Construisez VOTRE système.</strong></p><hr><h2 id="diapo-18-poursuivez-votre-voyage-🚀" tabindex="-1">Diapo 18 : Poursuivez votre voyage 🚀 <a class="header-anchor" href="#diapo-18-poursuivez-votre-voyage-🚀" aria-label="Permalink to &quot;Diapo 18 : Poursuivez votre voyage 🚀&quot;">​</a></h2><h3 id="ressources-gratuites-sur-carreau-app" tabindex="-1">Ressources gratuites sur carreau.app : <a class="header-anchor" href="#ressources-gratuites-sur-carreau-app" aria-label="Permalink to &quot;Ressources gratuites sur carreau.app :&quot;">​</a></h3><p><strong>📚 Analyses approfondies :</strong></p><ul><li><strong>La Zone</strong> - États de flux maîtres</li><li><strong>Force mentale</strong> - Gestion avancée du stress</li><li><strong>Dynamique d&#39;équipe</strong> - Communication et confiance</li><li><strong>Pleine conscience</strong> - Se concentrer sur le moment présent</li></ul><p><strong>🛠️ Outils pratiques :</strong></p><ul><li><strong>Modèle d&#39;objectif</strong> - Structurez votre développement</li><li><strong>Modèle de journal</strong> - Suivez vos progrès quotidiens</li><li><strong>Guide d&#39;atelier</strong> - Animez vos propres sessions</li></ul><p><strong>Tout est gratuit. Tout est accessible. Tout est conçu pour les joueurs d&#39;élite.</strong></p><hr><h2 id="diapositive-19-les-4-grandes-idees-💡" tabindex="-1">Diapositive 19 : Les 4 grandes idées 💡 <a class="header-anchor" href="#diapositive-19-les-4-grandes-idees-💡" aria-label="Permalink to &quot;Diapositive 19 : Les 4 grandes idées 💡&quot;">​</a></h2><h3 id="emportez-ces-articles-chez-vous" tabindex="-1">Emportez ces articles chez vous : <a class="header-anchor" href="#emportez-ces-articles-chez-vous" aria-label="Permalink to &quot;Emportez ces articles chez vous :&quot;">​</a></h3><p><strong>1️⃣ Le flow est une compétence, pas de la chance</strong> Vous pouvez apprendre à y accéder à la demande</p><p><strong>2️⃣ Votre voix intérieure FAÇONNE votre performance</strong> Soyez votre propre coach, ne vous critiquez pas.</p><p><strong>3️⃣ Outils simples qui fonctionnent sous pression</strong> Trois respirations. Une routine. Une réinitialisation. C&#39;est tout.</p><p><strong>4️⃣ La pratique rend PERMANENT</strong> Les compétences mentales nécessitent un entraînement, tout comme les compétences techniques.</p><h3 id="la-verite-1" tabindex="-1">La vérité : <a class="header-anchor" href="#la-verite-1" aria-label="Permalink to &quot;La vérité :&quot;">​</a></h3><p><strong>L&#39;entraînement mental n&#39;est pas mystique. Il est pratique.</strong></p><hr><h2 id="diapo-20-des-questions-parlons-en-💬" tabindex="-1">Diapo 20 : Des questions ? Parlons-en ! 💬 <a class="header-anchor" href="#diapo-20-des-questions-parlons-en-💬" aria-label="Permalink to &quot;Diapo 20 : Des questions ? Parlons-en ! 💬&quot;">​</a></h2><h1 id="discussion-ouverte" tabindex="-1">Discussion ouverte <a class="header-anchor" href="#discussion-ouverte" aria-label="Permalink to &quot;Discussion ouverte&quot;">​</a></h1><p><strong>Avez-vous des questions ?</strong></p><p><strong>Quelles expériences souhaitez-vous partager ?</strong></p><p><strong>Quels défis rencontrez-vous ?</strong></p><p><strong>Qu&#39;allez-vous essayer en premier ?</strong></p><p><em>Cette séance est la vôtre. Faisons en sorte qu&#39;elle vous soit profitable.</em></p><hr><h2 id="diapo-21-votre-defi-🎯" tabindex="-1">Diapo 21 : Votre défi 🎯 <a class="header-anchor" href="#diapo-21-votre-defi-🎯" aria-label="Permalink to &quot;Diapo 21 : Votre défi 🎯&quot;">​</a></h2><h1 id="mission-de-la-semaine" tabindex="-1">Mission de la semaine : <a class="header-anchor" href="#mission-de-la-semaine" aria-label="Permalink to &quot;Mission de la semaine :&quot;">​</a></h1><p><strong>1️⃣ Choisissez UN outil</strong> (Réinitialisation en 3 respirations, routine pré-tir, coach intérieur ou changement de mode)</p><p><strong>2️⃣ Pratiquez-le À CHAQUE séance</strong> (La régularité l&#39;emporte sur l&#39;intensité)</p><p><strong>3️⃣ Remarquez les changements</strong> (Suivez vos progrès)</p><p><strong>4️⃣ Partagez vos résultats</strong> (Avec vos partenaires d&#39;entraînement ou sur carreau.app)</p><h3 id="souviens-toi" tabindex="-1">Souviens-toi: <a class="header-anchor" href="#souviens-toi" aria-label="Permalink to &quot;Souviens-toi:&quot;">​</a></h3><p><strong>De petits changements → De grands résultats</strong></p><hr><h2 id="diapo-22-merci-🙏" tabindex="-1">Diapo 22 : Merci ! 🙏 <a class="header-anchor" href="#diapo-22-merci-🙏" aria-label="Permalink to &quot;Diapo 22 : Merci ! 🙏&quot;">​</a></h2><h1 id="tu-peux-le-faire" tabindex="-1">Tu peux le faire ! <a class="header-anchor" href="#tu-peux-le-faire" aria-label="Permalink to &quot;Tu peux le faire !&quot;">​</a></h1><p><strong>Ce que vous avez appris aujourd&#39;hui :</strong></p><ul><li>✅ Comment accéder aux états de flux</li><li>✅ Comment gérer sa voix intérieure critique</li><li>✅ Des outils pratiques qui fonctionnent sous pression</li><li>✅ Un plan d&#39;action clair pour cette semaine</li></ul><p><strong>Prochaines étapes :</strong></p><ol><li>Choisissez votre SEULE technique</li><li>Pratiquez-le régulièrement</li><li>Visitez carreau.app pour plus de ressources</li><li>Partagez vos progrès avec le groupe</li></ol><h3 id="le-voyage-commence-maintenant" tabindex="-1">Le voyage commence maintenant : <a class="header-anchor" href="#le-voyage-commence-maintenant" aria-label="Permalink to &quot;Le voyage commence maintenant :&quot;">​</a></h3><p><strong>L&#39;entraînement mental est pratique, pas mystique.</strong><strong>Commencez dès aujourd&#39;hui. Voyez les résultats bientôt.</strong></p><hr><p><em>Académie de Pétanque - Développement des joueurs élites</em><em>carreau.app - Ressources gratuites pour les joueurs d&#39;élite</em></p>',201)])])}]]);export{o as __pageData,r as default};
